-- ============================================================
-- E-Commerce Schema (ec_*) - Complete PostgreSQL Schema
-- ============================================================
-- Pattern: bigint generated by default as identity for PKs
-- Pattern: timestamp(6) for timestamps
-- Pattern: CHECK ((column)::text = ANY (ARRAY['VAL1'::character varying, ...]))
-- Pattern: Named constraint syntax for FKs
-- Pattern: ALTER TABLE ... OWNER TO postgres after each table
-- Pattern: CREATE INDEX after each table
-- ============================================================

-- ============================================================
-- GROUP 1: Language & Tags (No FK Dependencies)
-- ============================================================

CREATE TABLE ec_languages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    active BOOLEAN NOT NULL,
    default_language BOOLEAN NOT NULL,
    language_code VARCHAR(20) NOT NULL,
    language_name VARCHAR(100),
    native_name VARCHAR(100),
    rtl BOOLEAN NOT NULL,
    CONSTRAINT uq_ec_language UNIQUE (language_code)
);
ALTER TABLE ec_languages OWNER TO postgres;

CREATE TABLE ec_product_tags (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    slug VARCHAR(120) NOT NULL,
    tag_name VARCHAR(100) NOT NULL,
    CONSTRAINT uq_ec_tag UNIQUE (organization_id, slug)
);
ALTER TABLE ec_product_tags OWNER TO postgres;

CREATE TABLE ec_scheduled_jobs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    active BOOLEAN NOT NULL,
    cron_expression VARCHAR(100),
    error_message TEXT,
    job_name VARCHAR(200),
    last_result VARCHAR(20),
    last_run TIMESTAMP(6),
    next_run TIMESTAMP(6),
    organization_id BIGINT
);
ALTER TABLE ec_scheduled_jobs OWNER TO postgres;
CREATE INDEX idx_ec_job_org ON ec_scheduled_jobs(organization_id);

-- ============================================================
-- GROUP 2: Categories
-- ============================================================

CREATE TABLE ec_categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    active BOOLEAN NOT NULL,
    banner_url VARCHAR(700),
    category_code VARCHAR(50) NOT NULL,
    category_name VARCHAR(200) NOT NULL,
    deleted BOOLEAN NOT NULL,
    description TEXT,
    display_order INTEGER,
    icon VARCHAR(100),
    image_url VARCHAR(700),
    is_featured BOOLEAN NOT NULL,
    is_menu BOOLEAN NOT NULL,
    level_no INTEGER,
    meta_description VARCHAR(1000),
    meta_keywords VARCHAR(500),
    meta_title VARCHAR(255),
    short_description VARCHAR(500),
    slug VARCHAR(250) NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    parent_category_id BIGINT REFERENCES ec_categories(id),
    CONSTRAINT uq_ec_cat_code UNIQUE (organization_id, category_code),
    CONSTRAINT uq_ec_cat_slug UNIQUE (organization_id, slug)
);
ALTER TABLE ec_categories OWNER TO postgres;
CREATE INDEX idx_ec_cat_org ON ec_categories(organization_id);
CREATE INDEX idx_ec_cat_parent ON ec_categories(parent_category_id);
CREATE INDEX idx_ec_cat_slug ON ec_categories(slug);
CREATE INDEX idx_ec_cat_active ON ec_categories(active);
CREATE INDEX idx_ec_cat_featured ON ec_categories(is_featured);

CREATE TABLE ec_category_attributes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    active BOOLEAN NOT NULL,
    attribute_label VARCHAR(150),
    attribute_name VARCHAR(150) NOT NULL,
    created_at TIMESTAMP(6),
    data_type VARCHAR(30) NOT NULL,
    display_order INTEGER,
    filterable BOOLEAN NOT NULL,
    is_required BOOLEAN NOT NULL,
    searchable BOOLEAN NOT NULL,
    sortable BOOLEAN NOT NULL,
    updated_at TIMESTAMP(6),
    category_id BIGINT NOT NULL REFERENCES ec_categories(id),
    CONSTRAINT chk_ec_catattr_datatype CHECK ((data_type)::text = ANY (ARRAY['TEXT'::character varying, 'NUMBER'::character varying, 'BOOLEAN'::character varying, 'DATE'::character varying, 'LIST'::character varying, 'COLOR'::character varying]))
);
ALTER TABLE ec_category_attributes OWNER TO postgres;
CREATE INDEX idx_ec_catattr_cat ON ec_category_attributes(category_id);

-- ============================================================
-- GROUP 3: Product Catalog
-- ============================================================

CREATE TABLE ec_product_catalog (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    active BOOLEAN NOT NULL,
    best_seller BOOLEAN NOT NULL,
    deleted BOOLEAN NOT NULL,
    description TEXT,
    featured BOOLEAN NOT NULL,
    maximum_order_qty NUMERIC(12,2),
    minimum_order_qty NUMERIC(12,2),
    new_arrival BOOLEAN NOT NULL,
    product_title VARCHAR(300) NOT NULL,
    publish_date TIMESTAMP(6),
    published BOOLEAN NOT NULL,
    recommended BOOLEAN NOT NULL,
    return_policy TEXT,
    seo_description VARCHAR(1000),
    seo_keywords VARCHAR(500),
    seo_title VARCHAR(255),
    shipping_information TEXT,
    short_description VARCHAR(1000),
    slug VARCHAR(250) NOT NULL,
    trending BOOLEAN NOT NULL,
    warranty_information VARCHAR(500),
    youtube_video VARCHAR(500),
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    category_id BIGINT REFERENCES ec_categories(id),
    item_id BIGINT NOT NULL REFERENCES inv_items(id),
    CONSTRAINT uq_ec_prod_slug UNIQUE (organization_id, slug),
    CONSTRAINT uq_ec_prod_item UNIQUE (organization_id, item_id)
);
ALTER TABLE ec_product_catalog OWNER TO postgres;
CREATE INDEX idx_ec_prod_org ON ec_product_catalog(organization_id);
CREATE INDEX idx_ec_prod_item ON ec_product_catalog(item_id);
CREATE INDEX idx_ec_prod_cat ON ec_product_catalog(category_id);
CREATE INDEX idx_ec_prod_slug ON ec_product_catalog(slug);
CREATE INDEX idx_ec_prod_featured ON ec_product_catalog(featured);
CREATE INDEX idx_ec_prod_best ON ec_product_catalog(best_seller);
CREATE INDEX idx_ec_prod_trending ON ec_product_catalog(trending);
CREATE INDEX idx_ec_prod_pub ON ec_product_catalog(published, publish_date);
CREATE INDEX idx_ec_prod_active ON ec_product_catalog(active, deleted);

CREATE TABLE ec_product_images (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    active BOOLEAN,
    alt_text VARCHAR(500),
    created_at TIMESTAMP(6),
    created_by BIGINT,
    display_order INTEGER,
    image_url VARCHAR(700) NOT NULL,
    is_primary BOOLEAN NOT NULL,
    thumbnail_url VARCHAR(700),
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id)
);
ALTER TABLE ec_product_images OWNER TO postgres;
CREATE INDEX idx_ec_prodimg_prod ON ec_product_images(product_id);

CREATE TABLE ec_product_variants (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    active BOOLEAN NOT NULL,
    color VARCHAR(100),
    compare_price NUMERIC(18,2),
    created_at TIMESTAMP(6),
    created_by BIGINT,
    deleted BOOLEAN NOT NULL,
    height_override NUMERIC(12,3),
    length_override NUMERIC(12,3),
    selling_price NUMERIC(18,2),
    size_name VARCHAR(100),
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    variant_code VARCHAR(50),
    variant_name VARCHAR(200),
    weight_override NUMERIC(12,3),
    width_override NUMERIC(12,3),
    item_id BIGINT NOT NULL REFERENCES inv_items(id),
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    CONSTRAINT uq_ec_variant_item UNIQUE (product_id, item_id)
);
ALTER TABLE ec_product_variants OWNER TO postgres;
CREATE INDEX idx_ec_variant_prod ON ec_product_variants(product_id);
CREATE INDEX idx_ec_variant_item ON ec_product_variants(item_id);
CREATE INDEX idx_ec_variant_active ON ec_product_variants(active);

CREATE TABLE ec_product_attribute_values (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    attribute_value TEXT,
    category_attribute_id BIGINT NOT NULL REFERENCES ec_category_attributes(id),
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    CONSTRAINT uq_ec_prodattr UNIQUE (product_id, category_attribute_id)
);
ALTER TABLE ec_product_attribute_values OWNER TO postgres;
CREATE INDEX idx_ec_prodattr_prod ON ec_product_attribute_values(product_id);

CREATE TABLE ec_product_tag_map (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    tag_id BIGINT NOT NULL REFERENCES ec_product_tags(id),
    CONSTRAINT uq_ec_prod_tag UNIQUE (product_id, tag_id)
);
ALTER TABLE ec_product_tag_map OWNER TO postgres;
CREATE INDEX idx_ec_prodtag_prod ON ec_product_tag_map(product_id);

CREATE TABLE ec_product_analytics (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    analytics_date DATE NOT NULL,
    cart_additions INTEGER NOT NULL,
    conversion_rate NUMERIC(8,2),
    product_views INTEGER NOT NULL,
    purchases INTEGER NOT NULL,
    returns INTEGER NOT NULL,
    revenue NUMERIC(18,2),
    wishlist_count INTEGER NOT NULL,
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    CONSTRAINT uq_ec_prodana UNIQUE (product_id, analytics_date)
);
ALTER TABLE ec_product_analytics OWNER TO postgres;
CREATE INDEX idx_ec_prodana_prod ON ec_product_analytics(product_id);
CREATE INDEX idx_ec_prodana_date ON ec_product_analytics(analytics_date);

CREATE TABLE ec_review_summary (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    average_rating NUMERIC(3,2),
    rating1 INTEGER NOT NULL,
    rating2 INTEGER NOT NULL,
    rating3 INTEGER NOT NULL,
    rating4 INTEGER NOT NULL,
    rating5 INTEGER NOT NULL,
    recommendation_pct NUMERIC(5,2),
    total_reviews INTEGER NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    product_id BIGINT NOT NULL UNIQUE REFERENCES ec_product_catalog(id)
);
ALTER TABLE ec_review_summary OWNER TO postgres;
CREATE INDEX idx_ec_reviewsum_prod ON ec_review_summary(product_id);
CREATE INDEX idx_ec_reviewsum_org ON ec_review_summary(organization_id);

-- ============================================================
-- GROUP 4: Customers & Customer Sub-Entities
-- ============================================================

CREATE TABLE ec_customers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT REFERENCES sec_users(id),
    updated_at TIMESTAMP(6),
    updated_by BIGINT REFERENCES sec_users(id),
    active BOOLEAN NOT NULL,
    customer_code VARCHAR(50) NOT NULL,
    customer_name VARCHAR(200) NOT NULL,
    email VARCHAR(200),
    phone VARCHAR(50),
    mobile VARCHAR(50),
    gstin VARCHAR(50),
    pan VARCHAR(50),
    credit_limit NUMERIC(18,2),
    opening_balance NUMERIC(18,2),
    currency_code VARCHAR(10),
    exchange_rate NUMERIC(12,6),
    loyalty_points INTEGER DEFAULT 0,
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    account_id BIGINT REFERENCES acc_chart_of_accounts_sub(id),
    user_id BIGINT REFERENCES sec_users(id),
    CONSTRAINT uq_ec_cust_code UNIQUE (organization_id, customer_code),
    CONSTRAINT uq_ec_cust_email UNIQUE (organization_id, email)
);
ALTER TABLE ec_customers OWNER TO postgres;
CREATE INDEX idx_ec_cust_org ON ec_customers(organization_id);
CREATE INDEX idx_ec_cust_email ON ec_customers(email);
CREATE INDEX idx_ec_cust_account ON ec_customers(account_id);
CREATE INDEX idx_ec_cust_user ON ec_customers(user_id);

CREATE TABLE ec_customer_addresses (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    active BOOLEAN NOT NULL,
    address_type VARCHAR(20) NOT NULL,
    address_line1 VARCHAR(255) NOT NULL,
    address_line2 VARCHAR(255),
    city VARCHAR(100) NOT NULL,
    state VARCHAR(100) NOT NULL,
    country VARCHAR(100) NOT NULL,
    postal_code VARCHAR(20) NOT NULL,
    is_default BOOLEAN NOT NULL,
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    CONSTRAINT chk_ec_custaddr_type CHECK ((address_type)::text = ANY (ARRAY['BILLING'::character varying, 'SHIPPING'::character varying, 'BOTH'::character varying]))
);
ALTER TABLE ec_customer_addresses OWNER TO postgres;
CREATE INDEX idx_ec_custaddr_cust ON ec_customer_addresses(customer_id);
CREATE INDEX idx_ec_custaddr_type ON ec_customer_addresses(address_type);

CREATE TABLE ec_customer_devices (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    device_token VARCHAR(500),
    device_type VARCHAR(50),
    last_login TIMESTAMP(6),
    platform VARCHAR(50),
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id)
);
ALTER TABLE ec_customer_devices OWNER TO postgres;
CREATE INDEX idx_ec_custdev_cust ON ec_customer_devices(customer_id);

CREATE TABLE ec_customer_login_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    login_time TIMESTAMP(6),
    ip_address VARCHAR(50),
    user_agent TEXT,
    device_info VARCHAR(255),
    login_status VARCHAR(20) NOT NULL,
    failure_reason VARCHAR(255),
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    CONSTRAINT chk_ec_custlog_status CHECK ((login_status)::text = ANY (ARRAY['SUCCESS'::character varying, 'FAILURE'::character varying, 'LOCKED'::character varying]))
);
ALTER TABLE ec_customer_login_history OWNER TO postgres;
CREATE INDEX idx_ec_custlog_cust ON ec_customer_login_history(customer_id);

CREATE TABLE ec_customer_otp (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    expires_at TIMESTAMP(6) NOT NULL,
    otp_code VARCHAR(10) NOT NULL,
    otp_type VARCHAR(20) NOT NULL,
    updated_at TIMESTAMP(6),
    verified BOOLEAN NOT NULL,
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    CONSTRAINT chk_ec_custotp_type CHECK ((otp_type)::text = ANY (ARRAY['LOGIN'::character varying, 'REGISTRATION'::character varying, 'PASSWORD_RESET'::character varying, 'ORDER_CONFIRMATION'::character varying]))
);
ALTER TABLE ec_customer_otp OWNER TO postgres;
CREATE INDEX idx_ec_custotp_cust ON ec_customer_otp(customer_id);

CREATE TABLE ec_customer_wallet (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    balance NUMERIC(18,2) NOT NULL,
    created_at TIMESTAMP(6),
    currency_code VARCHAR(10),
    last_transaction_date TIMESTAMP(6),
    updated_at TIMESTAMP(6),
    customer_id BIGINT NOT NULL UNIQUE REFERENCES ec_customers(id)
);
ALTER TABLE ec_customer_wallet OWNER TO postgres;
CREATE INDEX idx_ec_custwal_cust ON ec_customer_wallet(customer_id);

-- ============================================================
-- GROUP 5: Cart
-- ============================================================

CREATE TABLE ec_cart (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    session_id VARCHAR(200),
    subtotal NUMERIC(18,2),
    tax_amount NUMERIC(18,2),
    discount_amount NUMERIC(18,2),
    total_amount NUMERIC(18,2),
    coupon_code VARCHAR(50),
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    customer_id BIGINT REFERENCES ec_customers(id)
);
ALTER TABLE ec_cart OWNER TO postgres;
CREATE INDEX idx_ec_cart_org ON ec_cart(organization_id);
CREATE INDEX idx_ec_cart_cust ON ec_cart(customer_id);
CREATE INDEX idx_ec_cart_session ON ec_cart(session_id);

CREATE TABLE ec_cart_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    discount_amount NUMERIC(18,2),
    quantity INTEGER NOT NULL,
    tax_amount NUMERIC(18,2),
    total_price NUMERIC(18,2),
    unit_price NUMERIC(18,2) NOT NULL,
    cart_id BIGINT NOT NULL REFERENCES ec_cart(id),
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    variant_id BIGINT REFERENCES ec_product_variants(id)
);
ALTER TABLE ec_cart_items OWNER TO postgres;
CREATE INDEX idx_ec_cartitem_cart ON ec_cart_items(cart_id);
CREATE INDEX idx_ec_cartitem_prod ON ec_cart_items(product_id);
CREATE INDEX idx_ec_cartitem_var ON ec_cart_items(variant_id);

-- ============================================================
-- GROUP 6: Orders
-- ============================================================

CREATE TABLE ec_orders (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    order_number VARCHAR(50) NOT NULL,
    order_date TIMESTAMP(6) NOT NULL,
    subtotal NUMERIC(18,2) NOT NULL,
    tax_amount NUMERIC(18,2),
    discount_amount NUMERIC(18,2),
    shipping_charge NUMERIC(18,2),
    total_amount NUMERIC(18,2) NOT NULL,
    paid_amount NUMERIC(18,2),
    balance_amount NUMERIC(18,2),
    order_status VARCHAR(30) NOT NULL,
    payment_status VARCHAR(30) NOT NULL,
    shipping_status VARCHAR(30),
    currency_code VARCHAR(10),
    exchange_rate NUMERIC(12,6),
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    journal_entry_id BIGINT REFERENCES acc_journal_entry_master(id),
    coupon_id BIGINT REFERENCES ec_coupon(id),
    shipping_method_id BIGINT REFERENCES ec_shipping_methods(id),
    CONSTRAINT uq_ec_order_number UNIQUE (organization_id, order_number),
    CONSTRAINT chk_ec_orders_status CHECK ((order_status)::text = ANY (ARRAY['PENDING'::character varying, 'CONFIRMED'::character varying, 'PROCESSING'::character varying, 'SHIPPED'::character varying, 'DELIVERED'::character varying, 'CANCELLED'::character varying, 'RETURNED'::character varying, 'REFUNDED'::character varying])),
    CONSTRAINT chk_ec_orders_paystatus CHECK ((payment_status)::text = ANY (ARRAY['PENDING'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'REFUNDED'::character varying, 'PARTIALLY_REFUNDED'::character varying])),
    CONSTRAINT chk_ec_orders_shpstatus CHECK ((shipping_status)::text = ANY (ARRAY['PENDING'::character varying, 'PROCESSING'::character varying, 'SHIPPED'::character varying, 'IN_TRANSIT'::character varying, 'DELIVERED'::character varying, 'FAILED'::character varying, 'RETURNED'::character varying]))
);
ALTER TABLE ec_orders OWNER TO postgres;
CREATE INDEX idx_ec_orders_org ON ec_orders(organization_id);
CREATE INDEX idx_ec_orders_cust ON ec_orders(customer_id);
CREATE INDEX idx_ec_orders_date ON ec_orders(order_date);
CREATE INDEX idx_ec_orders_status ON ec_orders(order_status);
CREATE INDEX idx_ec_orders_paystatus ON ec_orders(payment_status);
CREATE INDEX idx_ec_orders_je ON ec_orders(journal_entry_id);

CREATE TABLE ec_order_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    discount_amount NUMERIC(18,2),
    item_name VARCHAR(300) NOT NULL,
    quantity INTEGER NOT NULL,
    tax_amount NUMERIC(18,2),
    total_price NUMERIC(18,2) NOT NULL,
    unit_price NUMERIC(18,2) NOT NULL,
    order_id BIGINT NOT NULL REFERENCES ec_orders(id),
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    variant_id BIGINT REFERENCES ec_product_variants(id)
);
ALTER TABLE ec_order_items OWNER TO postgres;
CREATE INDEX idx_ec_orderitem_order ON ec_order_items(order_id);
CREATE INDEX idx_ec_orderitem_prod ON ec_order_items(product_id);
CREATE INDEX idx_ec_orderitem_var ON ec_order_items(variant_id);

CREATE TABLE ec_order_addresses (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    address_line1 VARCHAR(255) NOT NULL,
    address_line2 VARCHAR(255),
    address_type VARCHAR(20) NOT NULL,
    city VARCHAR(100) NOT NULL,
    contact_number VARCHAR(50),
    contact_person VARCHAR(200),
    country VARCHAR(100) NOT NULL,
    postal_code VARCHAR(20) NOT NULL,
    state VARCHAR(100) NOT NULL,
    order_id BIGINT NOT NULL REFERENCES ec_orders(id),
    CONSTRAINT chk_ec_ordaddr_type CHECK ((address_type)::text = ANY (ARRAY['BILLING'::character varying, 'SHIPPING'::character varying]))
);
ALTER TABLE ec_order_addresses OWNER TO postgres;
CREATE INDEX idx_ec_ordaddr_order ON ec_order_addresses(order_id);

CREATE TABLE ec_order_notes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    note TEXT NOT NULL,
    note_type VARCHAR(30),
    created_by BIGINT,
    order_id BIGINT NOT NULL REFERENCES ec_orders(id),
    CONSTRAINT chk_ec_ordnote_type CHECK ((note_type)::text = ANY (ARRAY['INTERNAL'::character varying, 'CUSTOMER'::character varying, 'VENDOR'::character varying]))
);
ALTER TABLE ec_order_notes OWNER TO postgres;
CREATE INDEX idx_ec_ordnote_order ON ec_order_notes(order_id);

CREATE TABLE ec_order_status_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    changed_at TIMESTAMP(6),
    remarks TEXT,
    from_status VARCHAR(30),
    to_status VARCHAR(30) NOT NULL,
    changed_by BIGINT,
    order_id BIGINT NOT NULL REFERENCES ec_orders(id)
);
ALTER TABLE ec_order_status_history OWNER TO postgres;
CREATE INDEX idx_ec_ordhist_order ON ec_order_status_history(order_id);

CREATE TABLE ec_order_delivery_slots (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    delivery_charge NUMERIC(18,2),
    delivery_notes TEXT,
    slot_date DATE NOT NULL,
    slot_time_from TIME NOT NULL,
    slot_time_to TIME NOT NULL,
    order_id BIGINT NOT NULL REFERENCES ec_orders(id)
);
ALTER TABLE ec_order_delivery_slots OWNER TO postgres;
CREATE INDEX idx_ec_ordslot_order ON ec_order_delivery_slots(order_id);

-- ============================================================
-- GROUP 7: Payments
-- ============================================================

CREATE TABLE ec_payments (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    payment_number VARCHAR(50) NOT NULL,
    payment_date TIMESTAMP(6) NOT NULL,
    payment_method VARCHAR(50) NOT NULL,
    payment_reference VARCHAR(200),
    amount NUMERIC(18,2) NOT NULL,
    payment_status VARCHAR(30) NOT NULL,
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    order_id BIGINT NOT NULL REFERENCES ec_orders(id),
    CONSTRAINT uq_ec_pay_number UNIQUE (organization_id, payment_number),
    CONSTRAINT chk_ec_pay_method CHECK ((payment_method)::text = ANY (ARRAY['CASH'::character varying, 'CARD'::character varying, 'BANK_TRANSFER'::character varying, 'CHEQUE'::character varying, 'ONLINE'::character varying, 'WALLET'::character varying, 'COD'::character varying])),
    CONSTRAINT chk_ec_pay_status CHECK ((payment_status)::text = ANY (ARRAY['PENDING'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'REFUNDED'::character varying, 'CANCELLED'::character varying]))
);
ALTER TABLE ec_payments OWNER TO postgres;
CREATE INDEX idx_ec_pay_org ON ec_payments(organization_id);
CREATE INDEX idx_ec_pay_order ON ec_payments(order_id);
CREATE INDEX idx_ec_pay_status ON ec_payments(payment_status);

CREATE TABLE ec_payment_transactions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    amount NUMERIC(18,2) NOT NULL,
    gateway_response TEXT,
    transaction_date TIMESTAMP(6),
    transaction_id VARCHAR(200),
    transaction_status VARCHAR(30),
    transaction_type VARCHAR(30),
    payment_id BIGINT NOT NULL REFERENCES ec_payments(id),
    CONSTRAINT chk_ec_paytxn_type CHECK ((transaction_type)::text = ANY (ARRAY['CAPTURE'::character varying, 'AUTHORIZE'::character varying, 'VOID'::character varying, 'REFUND'::character varying]))
);
ALTER TABLE ec_payment_transactions OWNER TO postgres;
CREATE INDEX idx_ec_paytxn_pay ON ec_payment_transactions(payment_id);
CREATE INDEX idx_ec_paytxn_txnid ON ec_payment_transactions(transaction_id);

-- ============================================================
-- GROUP 8: Shipping
-- ============================================================

CREATE TABLE ec_shipping (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    shipping_number VARCHAR(50) NOT NULL,
    shipping_date TIMESTAMP(6),
    estimated_delivery TIMESTAMP(6),
    delivered_date TIMESTAMP(6),
    carrier VARCHAR(100),
    tracking_number VARCHAR(200),
    shipping_status VARCHAR(30) NOT NULL,
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    order_id BIGINT NOT NULL REFERENCES ec_orders(id),
    CONSTRAINT uq_ec_ship_number UNIQUE (organization_id, shipping_number),
    CONSTRAINT chk_ec_ship_status CHECK ((shipping_status)::text = ANY (ARRAY['PENDING'::character varying, 'PROCESSING'::character varying, 'SHIPPED'::character varying, 'IN_TRANSIT'::character varying, 'DELIVERED'::character varying, 'FAILED'::character varying, 'RETURNED'::character varying]))
);
ALTER TABLE ec_shipping OWNER TO postgres;
CREATE INDEX idx_ec_ship_org ON ec_shipping(organization_id);
CREATE INDEX idx_ec_ship_order ON ec_shipping(order_id);
CREATE INDEX idx_ec_ship_track ON ec_shipping(tracking_number);

