    length NUMERIC(12,3),
    package_name VARCHAR(200),
    tracking_number VARCHAR(200),
    weight NUMERIC(12,3),
    width NUMERIC(12,3),
    shipping_id BIGINT NOT NULL REFERENCES ec_shipping(id)
);
ALTER TABLE ec_shipment_packages OWNER TO postgres;
CREATE INDEX idx_ec_shipack_ship ON ec_shipment_packages(shipping_id);

CREATE TABLE ec_shipping_tracking (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    event_date TIMESTAMP(6),
    event_location VARCHAR(255),
