    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    return_number VARCHAR(50) NOT NULL,
    return_date TIMESTAMP(6) NOT NULL,
    return_type VARCHAR(30) NOT NULL,
    return_reason TEXT,
    total_amount NUMERIC(18,2) NOT NULL,
    refund_amount NUMERIC(18,2),
    return_status VARCHAR(20) NOT NULL,
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    order_id BIGINT NOT NULL REFERENCES ec_orders(id),
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    journal_entry_id BIGINT REFERENCES acc_journal_entry_master(id),
    CONSTRAINT uq_ec_ret_number UNIQUE (organization_id, return_number),
    CONSTRAINT chk_ec_ret_type CHECK ((return_type)::text = ANY (ARRAY['FULL'::character varying, 'PARTIAL'::character varying])),
    CONSTRAINT chk_ec_ret_status CHECK ((return_status)::text = ANY (ARRAY['REQUESTED'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'PENDING_REFUND'::character varying, 'REFUNDED'::character varying, 'CLOSED'::character varying]))
);
