CREATE INDEX idx_ec_retitem_ret ON ec_return_items(return_id);
CREATE INDEX idx_ec_retitem_orditem ON ec_return_items(order_item_id);

CREATE TABLE ec_refunds (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    refund_number VARCHAR(50) NOT NULL,
    refund_date TIMESTAMP(6) NOT NULL,
