    refund_status VARCHAR(20) NOT NULL,
    notes TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    return_id BIGINT NOT NULL REFERENCES ec_returns(id),
    journal_entry_id BIGINT REFERENCES acc_journal_entry_master(id),
    CONSTRAINT uq_ec_ref_number UNIQUE (organization_id, refund_number),
    CONSTRAINT chk_ec_ref_method CHECK ((refund_method)::text = ANY (ARRAY['ORIGINAL_PAYMENT'::character varying, 'BANK_TRANSFER'::character varying, 'WALLET'::character varying, 'CASH'::character varying])),
    CONSTRAINT chk_ec_ref_status CHECK ((refund_status)::text = ANY (ARRAY['PENDING'::character varying, 'PROCESSING'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying]))
);
ALTER TABLE ec_refunds OWNER TO postgres;
CREATE INDEX idx_ec_ref_org ON ec_refunds(organization_id);
