ALTER TABLE ec_blog_categories OWNER TO postgres;
CREATE INDEX idx_ec_blogcat_org ON ec_blog_categories(organization_id);

CREATE TABLE ec_blog_posts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT REFERENCES sec_users(id),
    updated_at TIMESTAMP(6),
    updated_by BIGINT REFERENCES sec_users(id),
