    content TEXT,
    excerpt TEXT,
    featured_image VARCHAR(700),
    meta_description VARCHAR(1000),
    meta_title VARCHAR(255),
    publish_date TIMESTAMP(6),
    published BOOLEAN NOT NULL,
    slug VARCHAR(250) NOT NULL,
    tags VARCHAR(500),
    title VARCHAR(300) NOT NULL,
    blog_category_id BIGINT REFERENCES ec_blog_categories(id),
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT uq_ec_blogpost_slug UNIQUE (organization_id, slug)
);
ALTER TABLE ec_blog_posts OWNER TO postgres;
CREATE INDEX idx_ec_blogpost_org ON ec_blog_posts(organization_id);
CREATE INDEX idx_ec_blogpost_cat ON ec_blog_posts(blog_category_id);
CREATE INDEX idx_ec_blogpost_pub ON ec_blog_posts(published, publish_date);

CREATE TABLE ec_pages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT REFERENCES sec_users(id),
    updated_at TIMESTAMP(6),
    updated_by BIGINT REFERENCES sec_users(id),
    content TEXT,
    meta_description VARCHAR(1000),
    meta_title VARCHAR(255),
    publish_date TIMESTAMP(6),
    published BOOLEAN NOT NULL,
    slug VARCHAR(250) NOT NULL,
    title VARCHAR(300) NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT uq_ec_page_slug UNIQUE (organization_id, slug)
);
ALTER TABLE ec_pages OWNER TO postgres;
CREATE INDEX idx_ec_page_org ON ec_pages(organization_id);

CREATE TABLE ec_media_library (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
