    file_name VARCHAR(255) NOT NULL,
    file_path VARCHAR(700) NOT NULL,
    file_size BIGINT,
    file_type VARCHAR(100),
    height INTEGER,
    width INTEGER,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id)
);
ALTER TABLE ec_media_library OWNER TO postgres;
