CREATE INDEX idx_ec_media_type ON ec_media_library(file_type);

-- ============================================================
-- GROUP 21: Configuration & Settings
-- ============================================================

CREATE TABLE ec_url_redirects (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    active BOOLEAN NOT NULL,
    redirect_type VARCHAR(10) NOT NULL,
    source_url VARCHAR(700) NOT NULL,
    target_url VARCHAR(700) NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT uq_ec_redir_source UNIQUE (organization_id, source_url),
    CONSTRAINT chk_ec_redir_type CHECK ((redirect_type)::text = ANY (ARRAY['301'::character varying, '302'::character varying]))
);
ALTER TABLE ec_url_redirects OWNER TO postgres;
CREATE INDEX idx_ec_redir_org ON ec_url_redirects(organization_id);

CREATE TABLE ec_settings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    updated_at TIMESTAMP(6),
    description TEXT,
    setting_group VARCHAR(100),
    setting_key VARCHAR(200) NOT NULL,
    setting_value TEXT NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT uq_ec_setting UNIQUE (organization_id, setting_key)
);
ALTER TABLE ec_settings OWNER TO postgres;
CREATE INDEX idx_ec_setting_org ON ec_settings(organization_id);
CREATE INDEX idx_ec_setting_group ON ec_settings(setting_group);

CREATE TABLE ec_feature_flags (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    updated_at TIMESTAMP(6),
