    feature_key VARCHAR(100) NOT NULL,
    feature_name VARCHAR(200) NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT uq_ec_feature UNIQUE (organization_id, feature_key)
);
ALTER TABLE ec_feature_flags OWNER TO postgres;
CREATE INDEX idx_ec_feature_org ON ec_feature_flags(organization_id);

CREATE TABLE ec_menus (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
