    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    active BOOLEAN NOT NULL,
    display_order INTEGER,
    icon VARCHAR(100),
    menu_code VARCHAR(50) NOT NULL,
    menu_name VARCHAR(200) NOT NULL,
    slug VARCHAR(250),
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    parent_id BIGINT REFERENCES ec_menus(id),
    CONSTRAINT uq_ec_menu_code UNIQUE (organization_id, menu_code)
);
ALTER TABLE ec_menus OWNER TO postgres;
CREATE INDEX idx_ec_menu_org ON ec_menus(organization_id);
CREATE INDEX idx_ec_menu_parent ON ec_menus(parent_id);
