    slot_name VARCHAR(200) NOT NULL,
    start_time TIME NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT chk_ec_delslot_dow CHECK ((day_of_week)::integer = ANY (ARRAY[0, 1, 2, 3, 4, 5, 6]))
);
ALTER TABLE ec_delivery_slots OWNER TO postgres;
CREATE INDEX idx_ec_delslot_org ON ec_delivery_slots(organization_id);
CREATE INDEX idx_ec_delslot_day ON ec_delivery_slots(day_of_week);

