    is_active BOOLEAN NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT uq_ec_apiconf_name UNIQUE (organization_id, api_name)
);
ALTER TABLE ec_api_configurations OWNER TO postgres;
CREATE INDEX idx_ec_apiconf_org ON ec_api_configurations(organization_id);

