    organization_id BIGINT NOT NULL REFERENCES org_organizations(id)
);
ALTER TABLE ec_dashboard_kpis OWNER TO postgres;
CREATE INDEX idx_ec_kpi_org ON ec_dashboard_kpis(organization_id);
CREATE INDEX idx_ec_kpi_period ON ec_dashboard_kpis(kpi_period);

CREATE TABLE ec_audit_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    action VARCHAR(100) NOT NULL,
    entity_id BIGINT NOT NULL,
    entity_type VARCHAR(100) NOT NULL,
    ip_address VARCHAR(50),
    new_value TEXT,
    old_value TEXT,
    user_agent TEXT,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    created_by BIGINT REFERENCES sec_users(id)
);
ALTER TABLE ec_audit_logs OWNER TO postgres;
