CREATE INDEX idx_ec_audit_time ON ec_audit_logs(created_at);

CREATE TABLE ec_notifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT REFERENCES sec_users(id),
    is_read BOOLEAN NOT NULL,
    message TEXT NOT NULL,
    notification_type VARCHAR(50) NOT NULL,
    read_at TIMESTAMP(6),
    recipient_id BIGINT,
    recipient_type VARCHAR(30) NOT NULL,
    title VARCHAR(300) NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    CONSTRAINT chk_ec_notif_type CHECK ((notification_type)::text = ANY (ARRAY['ORDER'::character varying, 'PAYMENT'::character varying, 'SHIPPING'::character varying, 'RETURN'::character varying, 'REVIEW'::character varying, 'PROMOTIONAL'::character varying, 'SYSTEM'::character varying])),
    CONSTRAINT chk_ec_notif_recip CHECK ((recipient_type)::text = ANY (ARRAY['CUSTOMER'::character varying, 'USER'::character varying, 'ALL'::character varying]))
);
ALTER TABLE ec_notifications OWNER TO postgres;
CREATE INDEX idx_ec_notif_org ON ec_notifications(organization_id);
CREATE INDEX idx_ec_notif_recip ON ec_notifications(recipient_type, recipient_id);
CREATE INDEX idx_ec_notif_read ON ec_notifications(is_read);

