-- ============================================================
-- GROUP 25: Reviews & Review Sub-Entities
-- ============================================================

CREATE TABLE ec_reviews (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    created_by BIGINT,
    updated_at TIMESTAMP(6),
    updated_by BIGINT,
    active BOOLEAN NOT NULL,
    approved_at TIMESTAMP(6),
    approved_by BIGINT,
    cons TEXT,
    dislikes_count INTEGER NOT NULL,
    helpful_count INTEGER NOT NULL,
    likes_count INTEGER NOT NULL,
    pros TEXT,
    rating INTEGER NOT NULL,
    recommendation BOOLEAN,
    report_count INTEGER NOT NULL,
    review_status VARCHAR(20) NOT NULL,
    review_text TEXT,
    review_title VARCHAR(200),
    verified_purchase BOOLEAN NOT NULL,
    organization_id BIGINT NOT NULL REFERENCES org_organizations(id),
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    order_item_id BIGINT REFERENCES ec_order_items(id),
    product_id BIGINT NOT NULL REFERENCES ec_product_catalog(id),
    CONSTRAINT chk_ec_rev_status CHECK ((review_status)::text = ANY (ARRAY['PENDING'::character varying, 'APPROVED'::character varying, 'REJECTED'::character varying, 'HIDDEN'::character varying]))
);
ALTER TABLE ec_reviews OWNER TO postgres;
CREATE INDEX idx_ec_rev_prod ON ec_reviews(product_id);
CREATE INDEX idx_ec_rev_cust ON ec_reviews(customer_id);
CREATE INDEX idx_ec_rev_status ON ec_reviews(review_status);
CREATE INDEX idx_ec_rev_rating ON ec_reviews(rating);
CREATE INDEX idx_ec_rev_org ON ec_reviews(organization_id);

CREATE TABLE ec_review_images (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    image_url VARCHAR(700) NOT NULL,
    is_primary BOOLEAN,
    review_id BIGINT NOT NULL REFERENCES ec_reviews(id)
);
ALTER TABLE ec_review_images OWNER TO postgres;
CREATE INDEX idx_ec_revimg_rev ON ec_review_images(review_id);

CREATE TABLE ec_review_votes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMP(6),
    vote_type VARCHAR(10) NOT NULL,
    customer_id BIGINT NOT NULL REFERENCES ec_customers(id),
    review_id BIGINT NOT NULL REFERENCES ec_reviews(id),
    CONSTRAINT uq_ec_revvote UNIQUE (review_id, customer_id),
    CONSTRAINT chk_ec_revvote_type CHECK ((vote_type)::text = ANY (ARRAY['UP'::character varying, 'DOWN'::character varying]))
);
ALTER TABLE ec_review_votes OWNER TO postgres;
CREATE INDEX idx_ec_revvote_rev ON ec_review_votes(review_id);
CREATE INDEX idx_ec_revvote_cust ON ec_review_votes(customer_id);

